proc sql;
create table sg_rep_10_20 as
select a.*, b.*
from newsdata6 as a, safe_news_tic as b
where (a.tic = b.tic) and (a.news_date-10)<=b.visitday<=(a.news_date+20)
order by tic, fips, news_date, visitday;
quit;

proc sql;
create table spend as select
a.*, b.totalvisits_day
from spend as a left join safegraph as b
on a.stock_symbol = b.stock_symbol
and a.nfips = b.nfips
and a.visitday = b.visitday
order by stock_symbol, nfips, visitday;
quit;

proc sql;
create table spend_rep_10_20 as
select a.*, b.*
from newsdata6 as a, spend_news_tic as b
where (a.tic = b.tic) and (a.news_date-10)<=b.visitday<=(a.news_date+20)
