create table stacked_rep_10_20 as
select a.*, b.*
from newsdata6 as a, safe_news_tic as b
where (a.tic = b.tic) and (a.news_date-10)<=b.visitday<=(a.news_date+20)
order by tic, fips, news_date, visitday;
quit;

proc sql;
create table day_n21_n11 as select
a.*, b.visitday, b.totalvisits_day
from newsday as a, safegraph as b
where a.tic = b.stock_symbol
and a.nfips = b.nfips
and b.visitday - a.news_date >= -21
and b.visitday - a.news_date <= -11
order by tic, news_date, fips, visitday;
quit;

proc sql;
create table rep as
select a.*, b.lpermno as permno
from ticnews as a, crsp.ccmxpf_lnkhist2023 as b
where a.gvkey1=b.gvkey and b.linkprim in ('P', 'C') and
b.LINKTYPE in ('LU', 'LC') and
a.news_date>= b.LINKDT and (a.news_date <= b.LINKENDDT or missing(b.LINKENDDT))
order by gvkey1, news_date;
quit;

